"""Name helpers shared by the sign-up form and the vendor bridge."""
import unicodedata

_SPACES = {"\t", "\n", "\r", "\x0b", "\x0c", " ", "　"}


def normalize_name(text):
    """NFC-normalize, turn odd whitespace into plain spaces, collapse runs."""
    if text is None:
        return ""
    text = unicodedata.normalize("NFC", str(text))
    out = []
    for ch in text:
        if ch in _SPACES:
            ch = " "
        elif unicodedata.category(ch) in ("Cc", "Cf"):
            continue
        if ch == " " and out and out[-1] == " ":
            continue
        out.append(ch)
    return "".join(out).strip()


def mask_name(name):
    """홍길동 -> 홍*동, 이도 -> 이*, Kim Minseo -> K********o."""
    if len(name) <= 1:
        return name
    if len(name) == 2:
        return name[0] + "*"
    return name[0] + "*" * (len(name) - 2) + name[-1]


def vendor_name(name):
    """The vendor matches on the registered name without spaces."""
    return name.replace(" ", "")
"""Korean mobile numbers: accept what people type, store digits only."""
import re

_MOBILE = re.compile(r"^01[016789]\d{7,8}$")


def normalize_phone(raw):
    """'010-1234-5678', '+82 10 1234 5678', '(010)1234.5678' -> '01012345678'."""
    if raw is None:
        return ""
    digits = re.sub(r"\D", "", str(raw))
    if digits.startswith("82") and len(digits) in (11, 12):
        digits = "0" + digits[2:]
    return digits


def is_mobile(digits):
    return bool(_MOBILE.match(digits or ""))


def mask_phone(digits):
    """Keep the carrier prefix and the last four digits."""
    if len(digits) < 8:
        return "*" * len(digits)
    return f"{digits[:3]}-****-{digits[-4:]}"


def display_phone(digits):
    if len(digits) == 11:
        return f"{digits[:3]}-{digits[3:7]}-{digits[7:]}"
    if len(digits) == 10:
        return f"{digits[:3]}-{digits[3:6]}-{digits[6:]}"
    return digits
"""Date helpers (ISO strings only; no time zones involved)."""
import datetime as _dt


def parse_date(value):
    raw = str(value or "").strip()
    if len(raw) == 8 and raw.isdigit():
        raw = f"{raw[:4]}-{raw[4:6]}-{raw[6:]}"
    try:
        return _dt.date.fromisoformat(raw)
    except ValueError:
        raise ValueError(f"invalid date: {value!r}") from None


def compact(iso_date):
    """2001-02-03 -> 20010203"""
    return parse_date(iso_date).strftime("%Y%m%d")


def age_on(birth, today):
    """Full years (만 나이) on `today`."""
    b = parse_date(birth)
    years = today.year - b.year
    if (today.month, today.day) < (b.month, b.day):
        years -= 1
    return years
